gazE(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0646\u0635\u0641 \u0645\u0644\u0639\u0628\u0647\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0627\u0644\u062d\u0627\u0631\u0633 \u0645\u063a\u0644\u0642\u0629."},
gazF(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0648\u0627\u0633\u0639\u0629."},
gazG(){return"\u064a\u062a\u062c\u0627\u0648\u0632 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0645\u0646 \u0645\u0633\u0624\u0648\u0644\u064a\u0629 \u0627\u0644\u062d\u0627\u0631\u0633 \u0648\u062d\u062f\u0647."},
gazQ(){return"\u064a\u062a\u062c\u0645\u0639 \u0627\u0644\u062c\u0645\u064a\u0639 \u0641\u064a \u0627\u0644\u0639\u0645\u0642\u060c \u0648\u062a\u0628\u0642\u0649 \u0627\u0644\u0623\u062c\u0646\u062d\u0629 \u0641\u0627\u0631\u063a\u0629."},
